<?php declare(strict_types=1);require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('PUT','POST');apiCsrf();$uid=apiAuth(['admin','supplier','logistics']);$in=apiInput();$id=apiId($in['id']??0);$status=(string)($in['status']??'');$map=['processing'=>'Processing','shipped'=>'Out for Delivery','delivered'=>'Delivered','cancelled'=>'Cancelled'];if(!isset($map[$status]))apiError('Invalid status',422);$s=apiDb()->prepare('UPDATE orders SET order_status=? WHERE id=?');$s->execute([$map[$status],$id]);if(!$s->rowCount())apiError('Order not found',404);apiResponse(['id'=>$id,'order_status'=>$map[$status]]);